This is the standard fannkuch-redux benchmark. It prints the checksum, then `Pfannkuchen(N) = max`.

The usual algorithm generates permutations with the count-array (Heap-like) method and flips each one:

- Start with `perm1 = [0..n-1]`, `count = []`, `r = n`, `permCount = 0`, `checksum = 0`, `maxFlips = 0`.
- Loop:
  - While `r != 1`, set `count[r-1] = r` and decrement `r`.
  - Copy `perm1` into `perm`, then count flips: while `perm[0] != 0`, let `k = perm[0]`, reverse `perm[0..k]`, and increment the flip count.
  - Update `maxFlips`, and add `flips` to the checksum if `permCount` is even, otherwise subtract it.
  - Generate the next permutation: loop with `r` from 1 upward. If `r == n`, output the result. Otherwise rotate the first `r+1` elements of `perm1` left by one (`perm0 = perm1[0]`, shift, `perm1[r] = perm0`). Then decrement `count[r]`; if it is still above 0, break; otherwise increment `r`.
  - Increment `permCount`.

Edge cases:

- N=1 gives checksum 0 and `Pfannkuchen(1) = 0`. In the loop, `r=1` means no count entries are set. The flip count is 0 and the next-permutation step reaches `r == n == 1`, so it finishes correctly.
- Handle N=1 explicitly in the loop's termination check: after processing, start with `r=1`, and if `r >= n` then done.

Implementation of the next-permutation step:

```
while (true) {
  if (r == n) done;
  perm0 = perm1[0];
  for i in 0..r-1: perm1[i] = perm1[i+1];
  perm1[r] = perm0;
  count[r]--;
  if (count[r] > 0) break;
  r++;
}
```

Here `count[r]` must have been set earlier. For `r` from `n-1` down to 1 it is set by the `while (r != 1)` step, so `count[r] = r+1`. This matches the reference implementation, and the code uses typed arrays for speed.

```javascript
const n = parseInt(process.argv[2]);

function fannkuch(n) {
  const perm = new Int32Array(n);
  const perm1 = new Int32Array(n);
  const count = new Int32Array(n);
  for (let i = 0; i < n; i++) perm1[i] = i;
  let maxFlips = 0, permCount = 0, checksum = 0;
  let r = n;
  while (true) {
    while (r !== 1) {
      count[r - 1] = r;
      r--;
    }
    for (let i = 0; i < n; i++) perm[i] = perm1[i];
    let flips = 0;
    let k;
    while ((k = perm[0]) !== 0) {
      let i = 0, j = k;
      while (i < j) {
        const t = perm[i];
        perm[i] = perm[j];
        perm[j] = t;
        i++;
        j--;
      }
      flips++;
    }
    if (flips > maxFlips) maxFlips = flips;
    checksum += (permCount & 1) === 0 ? flips : -flips;

    while (true) {
      if (r >= n - 0 && r === n) {
        return [checksum, maxFlips];
      }
      const p0 = perm1[0];
      for (let i = 0; i < r; i++) perm1[i] = perm1[i + 1];
      perm1[r] = p0;
      count[r]--;
      if (count[r] > 0) break;
      r++;
    }
    permCount++;
  }
}

const res = fannkuch(n);
console.log(res[0] + "\nPfannkuchen(" + n + ") = " + res[1]);
```

